import type { LocaleMap, DetailedGuide } from './types';

export const detailedGuide = {
         en: {
            title: "Detailed workflows and important subtleties",
            intro: "These notes describe the current add-on behavior in addition to the 22 screenshot explanations above. Menu names below are the labels currently used by VFRNav.",
            items: [
               ["Know which settings you are changing", "VFRNav opens on Map and its own navigation switches among Map, Navlog, Charts, Settings, and Credits. The add-on Settings page is not the simulator's general EFB settings: it configures map providers, layer visibility and display, and (in the integrated EFB) optional panel-resizing tweaks. The resize controls are a workaround for the visible area, not a true increase in EFB size; items covered behind the panel may not be clickable. If the 2D resize controls become inaccessible, Ctrl+Shift+right-click restores the default size."],
               ["Understand the map's default layers", "With fresh defaults, Google map imagery and the France OACI chart are active; airport markers and France's AZBA areas are also enabled. The aircraft-position layer is disabled by default, so enable Settings > Map > Cheat > Plane if you want the aircraft marker. In the Layers panel, click a layer card to show or hide it and drag cards to change their drawing order. Settings can disable providers, choose airport types, and set zoom limits; a layer may therefore disappear when you zoom outside its configured range."],
               ["Create and manage flight plans", "On Map, open the flight-plan (Nav) panel and choose Create, then draw the route on the map by placing its vertices and finishing the drawing. The new route is added to the Nav panel and a corresponding Navlog tab; several routes can coexist. Use the route controls to activate or hide a route, reorder it, rename it, or remove it; drag its line vertices to reshape the route. The route and its map visibility are separate from the airport and chart layers."],
               ["Read and edit the Navlog carefully", "Each route has a Navlog tab; the Settings tab contains Compass (deviation) and Fuel models. Choose Edit to change supported leg fields, then Done to leave edit mode. Initial planning values include a 95-knot default speed, 300 loaded-fuel units, and 15 minutes/30 units for taxi time/consumption; these are defaults, not verified aircraft data. Enter values and presets appropriate to the aircraft and conditions, and treat calculated time, fuel, and headings as planning aids rather than guaranteed results."],
               ["Use only implemented chart sources", "In Charts choose Open, then Local or SIA. Local opens a PDF from the host computer and needs the VFRNav server/host file bridge to be available; you can give the document a page name. SIA accepts French aerodrome codes in the LF** format. TEMSI and Weather Fronts appear as source tabs, but the current code marks them as not yet implemented. In the PDF viewer, use the page arrows and +/- buttons; wheel scrolls vertically, Ctrl+wheel scrolls horizontally, Alt/Shift+wheel zooms, and left-button drag pans."],
               ["Read airport and AZBA data in context", "Enable the Airports layer and zoom in to its visibility range (default minimum zoom 8), then select an airport marker. The popup opens METAR/TAF and may offer frequencies, runways, transitions, or fuel depending on available airport data; its Charts tab is only added for French LF-prefixed airports. Airport-type filters are in Settings > Map > Airports. AZBA polygons represent scheduled French activity areas: select one to inspect its activity intervals, upper/lower limits, and remarks. Schedules are time-sensitive information, not an ATC clearance; verify current official information before flight."],
               ["Flight recording is automatic", "The integrated EFB samples aircraft position while the simulator reports the aircraft airborne; there is no start-record button. A record is saved after landing only when the flight lasted more than five seconds and a valid non-zero touchdown speed was reported. At most the 15 latest records are retained. In Map > Records, toggle tracks on the map, rename or delete a record, and use the review controls to adjust the profile; Alt+Shift+drag rotates the review map, and dragging the person marker changes its viewpoint. Settings > Data > Cleanup permanently clears the stored flight records after confirmation."],
               ["Know when the server is required", "Navlog Import and Export operate on JSON files in the standalone app; Upload sends the current plans to the connected simulator EFB and is unavailable when that connection is absent (and in the embedded app). Exporting Charts PDFs to the simulator also requires a connection and is available from the standalone view. Local document access and cross-app transfer rely on the VFRNav server or the host's file bridge, so check the connection status if those controls are unavailable. Server/external-browser features can differ by package and version; use the instructions included with your downloaded build."]
            ]
         },
         fr: {
            title: "Procédures détaillées et points importants",
            intro: "Ces précisions complètent les 22 explications de captures ci-dessus et décrivent le comportement actuel de l'extension.",
            items: [
               ["Distinguer les réglages", "VFRNav s'ouvre sur Carte et propose Carte, Journal, Cartes, Réglages et Crédits. Les réglages de l'extension ne sont pas ceux de l'EFB général de MSFS : ils configurent les sources cartographiques, les calques et, dans l'EFB intégré, des ajustements facultatifs du panneau. Le redimensionnement ne modifie que la zone visible et peut laisser des éléments masqués non cliquables. Si les commandes 2D deviennent inaccessibles, Ctrl+Maj+clic droit restaure la taille par défaut."],
               ["Comprendre les calques par défaut", "Avec les réglages initiaux, le fond Google et la carte OACI de France sont actifs, ainsi que les aérodromes et les zones AZBA. Le calque de position de l'avion est désactivé : activez Réglages > Carte > Cheat > Plane pour l'afficher. Dans le panneau Calques, cliquez sur une carte pour afficher/masquer le calque et faites-la glisser pour modifier l'ordre. Les réglages permettent de désactiver des sources, filtrer les types d'aérodromes et définir des plages de zoom ; un calque peut donc disparaître lorsque vous changez d'échelle."],
               ["Créer et gérer un plan de vol", "Dans Carte, ouvrez le panneau de plan de vol (Nav), choisissez Create, puis tracez la route sur la carte en plaçant ses sommets et en terminant le tracé. La route apparaît dans Nav et crée un onglet Journal correspondant ; plusieurs routes peuvent coexister. Les commandes permettent d'activer/masquer, réordonner, renommer ou supprimer une route ; faites glisser ses sommets pour la modifier. La visibilité de la route est indépendante de celle des calques de carte."],
               ["Lire et modifier le journal", "Chaque route possède son onglet Journal ; l'onglet Settings contient les modèles Compass (déviation) et Fuel. Choisissez Edit pour modifier les champs pris en charge, puis Done pour quitter l'édition. Les valeurs initiales comprennent une vitesse de 95 kt, 300 unités de carburant et 15 min/30 unités pour le temps/la consommation au roulage : ce sont des valeurs par défaut, pas les données vérifiées de votre avion. Renseignez des valeurs adaptées et considérez temps, carburant et caps calculés comme des aides, jamais comme des garanties."],
               ["Utiliser les sources de cartes disponibles", "Dans Cartes, choisissez Open puis Local ou SIA. Local ouvre un PDF de l'ordinateur et nécessite le serveur VFRNav ou la passerelle de fichiers de l'hôte ; vous pouvez nommer la page du document. SIA accepte les codes d'aérodrome français au format LF**. TEMSI et Weather Fronts sont proposés, mais le code actuel les indique comme non implémentés. Dans le lecteur PDF, utilisez les flèches et +/- ; la molette défile verticalement, Ctrl+molette horizontalement, Alt/Maj+molette zoome et le glisser avec clic gauche déplace la page."],
               ["Interpréter les informations d'aérodrome et AZBA", "Activez le calque Aérodromes et zoomez dans sa plage de visibilité (zoom minimal 8 par défaut), puis sélectionnez un symbole. La fenêtre affiche METAR/TAF et peut proposer fréquences, pistes, transitions ou carburants selon les données disponibles ; l'onglet Cartes n'est ajouté que pour les aérodromes français dont l'identifiant commence par LF. Les filtres de type se trouvent dans Réglages > Carte > Airports. Les zones AZBA indiquent une activité française programmée : sélectionnez-en une pour consulter horaires, limites hautes/basses et remarques. Ce calendrier n'est pas une autorisation ATC ; vérifiez l'information officielle à jour."],
               ["L'enregistrement est automatique", "L'EFB intégré échantillonne la position lorsque le simulateur indique que l'avion est en vol ; il n'y a pas de bouton de démarrage. Le vol est enregistré après l'atterrissage seulement s'il a duré plus de cinq secondes et si une vitesse de toucher non nulle est disponible. Seuls les 15 vols les plus récents sont conservés. Dans Carte > Records, affichez/masquez les traces, renommez ou supprimez un vol ; Alt+Maj+glisser fait pivoter la carte de revue et l'icône de personne déplaçable change le point de vue. Réglages > Data > Cleanup efface définitivement les traces après confirmation."],
               ["Savoir quand le serveur est nécessaire", "Dans l'application autonome, Import et Export du Journal manipulent des fichiers JSON ; Upload envoie les plans à l'EFB du simulateur connecté et est indisponible sans connexion (ainsi que dans l'application intégrée). L'export des PDF depuis Cartes vers le simulateur nécessite également une connexion et s'effectue depuis la vue autonome. L'accès aux fichiers locaux et les transferts entre applications dépendent du serveur VFRNav ou de la passerelle de fichiers de l'hôte. Les fonctions serveur/EFB externe varient selon le paquet et la version : suivez les instructions du téléchargement utilisé."]
            ]
         },
         de: {
            title: "Detaillierte Abläufe und wichtige Hinweise",
            intro: "Diese Hinweise ergänzen die 22 Screenshot-Erklärungen und beschreiben das aktuelle Verhalten des Add-ons.",
            items: [
               ["Einstellungen richtig zuordnen", "VFRNav startet auf Map und bietet Map, Navlog, Charts, Settings und Credits. Die Add-on-Einstellungen sind nicht die allgemeinen MSFS-EFB-Einstellungen: Sie steuern Kartenquellen, Ebenen und im integrierten EFB optionale Panel-Anpassungen. Die Größenänderung betrifft nur den sichtbaren Bereich; verdeckte Inhalte können unanklickbar bleiben. Wenn die 2D-Größensteuerung unerreichbar ist, setzt Ctrl+Shift+Rechtsklick die Standardgröße zurück."],
               ["Standard-Kartenebenen verstehen", "Bei frischen Standardeinstellungen sind Google-Kartenbilder und die französische OACI-Karte aktiv, ebenso Flugplätze und AZBA-Gebiete. Die Flugzeugpositions-Ebene ist zunächst aus; aktivieren Sie Settings > Map > Cheat > Plane, um das Flugzeug einzublenden. Im Ebenenfenster schaltet ein Klick eine Ebene ein/aus; Ziehen ändert die Zeichenreihenfolge. Unter Settings lassen sich Quellen, Flugplatztypen und Zoomgrenzen konfigurieren; außerhalb des Zoom-Bereichs verschwindet eine Ebene."],
               ["Flugpläne erstellen und verwalten", "Öffnen Sie auf Map das Flugplan-/Nav-Fenster und wählen Sie Create. Zeichnen Sie die Route durch gesetzte Punkte auf der Karte und beenden Sie die Zeichnung. Die Route erscheint im Nav-Fenster und erhält einen Navlog-Reiter; mehrere Routen sind möglich. Die Routenschaltflächen aktivieren/verbergen, sortieren, benennen oder löschen eine Route; ziehen Sie ihre Linienpunkte, um den Verlauf zu ändern. Die Routenanzeige ist unabhängig von Kartenebenen."],
               ["Navlog lesen und sorgfältig bearbeiten", "Jede Route hat einen eigenen Navlog-Reiter; Settings enthält Compass- und Fuel-Modelle. Mit Edit ändern Sie unterstützte Streckenfelder, Done beendet die Bearbeitung. Anfangswerte sind unter anderem 95 kt Geschwindigkeit, 300 Einheiten Kraftstoff sowie 15 Minuten/30 Einheiten für Rollzeit/-verbrauch; dies sind Vorgaben, keine geprüften Flugzeugdaten. Tragen Sie passende Flugzeug- und Wetterwerte ein und betrachten Sie berechnete Zeiten, Kraftstoffmengen und Kurse nur als Planungshilfe."],
               ["Nur verfügbare Kartenquellen verwenden", "Wählen Sie unter Charts Open und dann Local oder SIA. Local öffnet ein PDF vom Host und benötigt den VFRNav-Server bzw. die Dateiübertragung des Hosts; Sie können dem Dokument einen Seitennamen geben. SIA akzeptiert französische Flugplatzcodes im Format LF**. TEMSI und Weather Fronts werden zwar als Reiter angezeigt, sind im aktuellen Code aber noch nicht implementiert. Im PDF-Viewer dienen Pfeile und +/- zur Navigation; Rad scrollt vertikal, Ctrl+Rad horizontal, Alt/Shift+Rad zoomt und Ziehen mit linker Taste verschiebt."],
               ["Flugplatz- und AZBA-Daten richtig einordnen", "Aktivieren Sie die Flugplatzebene und zoomen Sie in den sichtbaren Bereich (Standard-Minimalzoom 8); wählen Sie dann ein Symbol. Das Fenster zeigt METAR/TAF und abhängig von verfügbaren Daten Frequenzen, Pisten, Übergänge oder Kraftstoff; eine Karten-Registerkarte erscheint nur bei französischen LF-Flugplätzen. Filter finden Sie unter Settings > Map > Airports. AZBA-Flächen zeigen geplante französische Aktivitätszeiten; wählen Sie eine Zone für Zeiten, Ober-/Untergrenzen und Hinweise. Das ist keine ATC-Freigabe – prüfen Sie vor dem Flug offizielle aktuelle Informationen."],
               ["Flüge werden automatisch aufgezeichnet", "Das integrierte EFB erfasst die Position, wenn der Simulator das Flugzeug als in der Luft meldet; eine Aufnahmetaste gibt es nicht. Nach der Landung wird nur gespeichert, wenn der Flug länger als fünf Sekunden dauerte und eine gültige, von null verschiedene Aufsetzgeschwindigkeit vorliegt. Es bleiben höchstens die 15 neuesten Flüge erhalten. Unter Map > Records können Sie Spuren ein-/ausblenden, umbenennen oder löschen; Alt+Shift+Ziehen dreht die Auswertungskarte, das verschiebbare Personensymbol ändert den Blickpunkt. Settings > Data > Cleanup löscht nach Bestätigung alle gespeicherten Flüge."],
               ["Wissen, wann der Server benötigt wird", "Import und Export im Navlog der Standalone-App verwenden JSON-Dateien; Upload sendet Pläne an das verbundene Simulator-EFB und ist ohne Verbindung sowie im integrierten App-Modus deaktiviert. Auch der PDF-Export aus Charts zum Simulator benötigt eine Verbindung und erfolgt in der Standalone-Ansicht. Lokale Dateien und App-übergreifende Übertragung benötigen den VFRNav-Server oder die Dateiübertragung des Hosts. Server- und externe-EFB-Funktionen unterscheiden sich je nach Paket und Version; beachten Sie die Hinweise Ihres Downloads."]
            ]
         },
         es: {
            title: "Flujos detallados y matices importantes",
            intro: "Estas notas amplían las 22 explicaciones de capturas y describen el comportamiento actual del complemento.",
            items: [
               ["Distingue los ajustes", "VFRNav se abre en Map y ofrece Map, Navlog, Charts, Settings y Credits. Los ajustes del complemento no son los ajustes generales del EFB de MSFS: configuran mapas, capas y ajustes opcionales del panel dentro del EFB integrado. El redimensionado solo cambia el área visible y puede dejar elementos cubiertos sin poder pulsarlos. Si no alcanzas los controles 2D, Ctrl+Shift+clic derecho restaura el tamaño predeterminado."],
               ["Capas predeterminadas", "Con los valores iniciales están activas las imágenes de Google, la carta OACI de Francia, los aeródromos y las zonas AZBA. La capa de posición del avión empieza desactivada; activa Settings > Map > Cheat > Plane para verla. En Layers, haz clic en una tarjeta para mostrar/ocultar la capa y arrástrala para cambiar el orden. Settings permite desactivar fuentes, filtrar tipos de aeródromo y definir límites de zoom; una capa puede desaparecer al salir de su rango."],
               ["Crear y administrar planes", "En Map, abre el panel del plan de vuelo (Nav) y elige Create; dibuja la ruta colocando sus vértices en el mapa y termina el trazado. La ruta aparece en Nav y crea una pestaña de Navlog; pueden coexistir varias. Los controles permiten activar/ocultar, reordenar, renombrar o eliminar rutas; arrastra los vértices para cambiar el trazado. La visibilidad de la ruta es independiente de las capas del mapa."],
               ["Leer y editar el Navlog", "Cada ruta tiene su pestaña Navlog; Settings contiene los modelos Compass y Fuel. Pulsa Edit para cambiar los campos de tramo disponibles y Done para salir de edición. Entre los valores iniciales hay una velocidad de 95 kt, 300 unidades de combustible y 15 min/30 unidades para tiempo/consumo de rodaje; son valores predeterminados, no datos verificados de tu avión. Introduce los valores apropiados y considera los cálculos de tiempo, combustible y rumbo como ayuda de planificación, no como garantía."],
               ["Usa solo las fuentes de cartas implementadas", "En Charts elige Open y luego Local o SIA. Local abre un PDF del equipo anfitrión y necesita el servidor VFRNav o la integración de archivos del anfitrión; puedes asignar un nombre a la página. SIA acepta códigos de aeródromo franceses con formato LF**. TEMSI y Weather Fronts aparecen como pestañas, pero el código actual indica que aún no están implementados. En el lector PDF usa las flechas y +/-; la rueda desplaza verticalmente, Ctrl+rueda horizontalmente, Alt/Shift+rueda amplía y arrastrar con el botón izquierdo desplaza la página."],
               ["Interpreta datos de aeródromos y AZBA", "Activa la capa de aeródromos y amplía hasta su rango visible (zoom mínimo 8 por defecto); selecciona un símbolo. La ventana muestra METAR/TAF y puede incluir frecuencias, pistas, transiciones o combustible según los datos; la pestaña Charts solo se añade para aeródromos franceses cuyo código empieza por LF. Los filtros están en Settings > Map > Airports. Las áreas AZBA muestran actividad francesa programada: selecciónalas para consultar horarios, límites superior/inferior y notas. No equivalen a una autorización ATC; comprueba la información oficial vigente."],
               ["La grabación de vuelos es automática", "El EFB integrado registra la posición mientras el simulador indica que el avión está en el aire; no hay botón de inicio. Solo guarda el vuelo tras aterrizar si duró más de cinco segundos y se informó una velocidad de toma válida distinta de cero. Conserva como máximo los 15 vuelos más recientes. En Map > Records muestra/oculta rutas, cambia sus nombres o elimínalas; Alt+Shift+arrastrar gira el mapa de revisión y el marcador de persona arrastrable cambia el punto de vista. Settings > Data > Cleanup borra todos los registros guardados tras confirmar."],
               ["Cuándo se necesita el servidor", "Import y Export del Navlog en la aplicación independiente usan archivos JSON; Upload envía los planes al EFB del simulador conectado y se desactiva sin conexión o dentro de la aplicación integrada. Exportar PDF de Charts al simulador también requiere conexión. El acceso a archivos locales y las transferencias entre aplicaciones dependen del servidor VFRNav o de la integración de archivos del anfitrión. Las funciones de servidor/EFB externo pueden variar según paquete y versión; consulta las instrucciones incluidas con tu descarga."]
            ]
         },
         it: {
            title: "Procedure dettagliate e aspetti importanti",
            intro: "Queste note ampliano le 22 spiegazioni delle schermate e descrivono il comportamento attuale dell'add-on.",
            items: [
               ["Distinguere le impostazioni", "VFRNav si apre su Map e offre Map, Navlog, Charts, Settings e Credits. Le impostazioni dell'add-on non sono quelle generali dell'EFB MSFS: configurano mappe, livelli e modifiche facoltative al pannello nell'EFB integrato. Il ridimensionamento cambia solo l'area visibile e può lasciare non cliccabili gli elementi coperti. Se i controlli 2D diventano inaccessibili, Ctrl+Shift+clic destro ripristina la dimensione predefinita."],
               ["Livelli predefiniti", "Con le impostazioni iniziali sono attive le immagini Google, la carta OACI francese, gli aeroporti e le aree AZBA. Il livello della posizione dell'aereo è disattivato: abilita Settings > Map > Cheat > Plane per mostrarlo. In Layers, clicca una scheda per mostrare/nascondere il livello e trascinala per cambiare l'ordine. Settings consente di disabilitare fonti, filtrare i tipi di aeroporto e impostare limiti di zoom; un livello scompare fuori dal proprio intervallo."],
               ["Creare e gestire piani di volo", "In Map apri il pannello del piano (Nav), scegli Create e disegna la rotta posizionando i vertici sulla mappa, quindi termina il disegno. La rotta appare in Nav e crea una scheda Navlog; possono esistere più rotte. I controlli consentono di attivare/nascondere, riordinare, rinominare o eliminare una rotta; trascina i vertici per modificarla. La visibilità della rotta è indipendente dai livelli cartografici."],
               ["Leggere e modificare il Navlog", "Ogni rotta ha una scheda Navlog; Settings contiene i modelli Compass e Fuel. Premi Edit per modificare i campi disponibili e Done per uscire dalla modifica. I valori iniziali includono velocità 95 kt, 300 unità di carburante e 15 min/30 unità per tempo/consumo di rullaggio: sono valori predefiniti, non dati verificati dell'aeromobile. Inserisci dati adeguati e considera tempi, carburante e prua calcolati solo come supporto alla pianificazione."],
               ["Usare le fonti carta implementate", "In Charts scegli Open, quindi Local o SIA. Local apre un PDF dal computer e richiede il server VFRNav o il ponte file dell'host; puoi assegnare un nome alla pagina. SIA accetta codici aeroportuali francesi nel formato LF**. TEMSI e Weather Fronts sono schede visibili, ma il codice attuale le indica come non ancora implementate. Nel visualizzatore PDF usa frecce e +/-; la rotella scorre verticalmente, Ctrl+rotella orizzontalmente, Alt/Shift+rotella ingrandisce e il trascinamento col tasto sinistro sposta la pagina."],
               ["Interpretare dati aeroportuali e AZBA", "Attiva il livello aeroporti e ingrandisci fino al suo intervallo visibile (zoom minimo predefinito 8), poi seleziona un simbolo. Il popup mostra METAR/TAF e può offrire frequenze, piste, transizioni o carburante secondo i dati disponibili; la scheda Charts compare solo per aeroporti francesi con codice LF. I filtri sono in Settings > Map > Airports. Le aree AZBA mostrano attività francesi programmate: selezionale per orari, limiti superiore/inferiore e note. Non sono un'autorizzazione ATC: verifica le informazioni ufficiali aggiornate."],
               ["La registrazione è automatica", "L'EFB integrato registra la posizione quando il simulatore indica che l'aereo è in volo; non c'è un pulsante di avvio. Il volo viene salvato dopo l'atterraggio solo se è durato più di cinque secondi e se è disponibile una velocità di touchdown valida e non nulla. Si conservano al massimo gli ultimi 15 voli. In Map > Records puoi mostrare/nascondere le tracce, rinominarle o eliminarle; Alt+Shift+trascina ruota la mappa di revisione e trascinare l'icona della persona cambia il punto di vista. Settings > Data > Cleanup elimina tutti i record dopo conferma."],
               ["Quando serve il server", "Import ed Export del Navlog nell'app autonoma gestiscono file JSON; Upload invia i piani all'EFB del simulatore connesso ed è disabilitato senza connessione e nell'app integrata. Anche l'esportazione dei PDF da Charts al simulatore richiede una connessione. Accesso ai file locali e trasferimenti tra app dipendono da VFRNav Server o dal ponte file dell'host. Le funzioni server/EFB esterno variano per pacchetto e versione: consulta le istruzioni della build scaricata."]
            ]
         },
         ja: {
            title: "詳しい操作手順と注意点",
            intro: "上記22項目のスクリーンショット説明に加え、現在のアドオンの動作と重要な違いを説明します。",
            items: [
               ["設定の区別", "VFRNavはMapで起動し、Map、Navlog、Charts、Settings、Creditsを切り替えます。アドオンのSettingsはMSFSの一般EFB設定とは別で、地図ソースやレイヤー、統合EFBの任意のパネル調整を設定します。サイズ変更は表示領域だけを変えるため、背後の項目がクリックできない場合があります。2Dのサイズ操作ができなくなった場合はCtrl+Shift+右クリックで既定サイズに戻します。"],
               ["初期レイヤー", "初期設定ではGoogle地図とフランスOACIチャート、空港、AZBAエリアが有効です。機体位置レイヤーは初期状態で無効です。表示するにはSettings > Map > Cheat > Planeを有効にします。Layersパネルのカードをクリックすると表示を切り替え、ドラッグすると描画順を変更できます。Settingsでソース、空港種別、ズーム範囲を設定でき、範囲外ではレイヤーが非表示になります。"],
               ["フライトプランの作成", "Mapでフライトプラン（Nav）パネルを開き、Createを選んで地図上にルート点を置き、描画を終了します。ルートはNavに追加され、対応するNavlogタブが作られます。複数ルートを保持できます。ルート操作で表示切替、順序変更、名前変更、削除を行い、線の頂点をドラッグして経路を修正します。ルート表示と地図レイヤー表示は別々です。"],
               ["Navlogの確認と編集", "ルートごとにNavlogタブがあり、SettingsにはCompassとFuelのモデルがあります。Editで対応フィールドを編集し、Doneで終了します。初期値は速度95 kt、搭載燃料300単位、タキシー時間15分・消費30単位などで、実機に確認された値ではありません。機体と条件に合った値を設定し、時間・燃料・針路の計算は計画補助として扱ってください。"],
               ["実装済みのチャートソース", "ChartsでOpenを選び、LocalまたはSIAを選択します。LocalはPCのPDFを開き、VFRNavサーバーまたはホストのファイル連携が必要です。文書のタブ名も設定できます。SIAで使えるのはLF**形式のフランス空港コードです。TEMSIとWeather Frontsのタブは表示されますが、現行コードでは未実装です。PDFでは矢印と+/-を使い、ホイールで縦スクロール、Ctrl+ホイールで横スクロール、Alt/Shift+ホイールで拡大、左ドラッグで移動します。"],
               ["空港情報とAZBA", "空港レイヤーを有効にし、表示範囲（初期の最小ズームは8）まで拡大してマーカーを選びます。METAR/TAFに加え、データがあれば周波数、滑走路、遷移高度、燃料を表示します。ChartsタブはLFで始まるフランス空港だけに表示されます。種類フィルターはSettings > Map > Airportsにあります。AZBAは予定されたフランスの活動エリアです。選択すると時間、高度上限/下限、備考が見られますが、ATC許可ではありません。最新の公式情報を確認してください。"],
               ["飛行記録は自動", "統合EFBはシミュレーターが飛行中と判定している間、機体位置を記録します。開始ボタンはありません。着陸後、飛行時間が5秒を超え、0以外の有効な接地速度がある場合に保存されます。保存は最新15件までです。Map > Recordsで航跡の表示切替、名前変更、削除ができます。Alt+Shift+ドラッグでレビュー地図を回転し、人のマーカーをドラッグして視点を変えます。Settings > Data > Cleanupは確認後に全記録を消去します。"],
               ["サーバーが必要な操作", "スタンドアロン版NavlogのImport/ExportはJSONファイルを扱います。Uploadは接続中のシミュレーターEFBへプランを送信し、未接続時または統合アプリ内では使用できません。ChartsのPDFをシミュレーターへ送る場合も接続が必要です。ローカル文書やアプリ間転送はVFRNavサーバーまたはホストのファイル連携に依存します。サーバーや外部ブラウザーEFBの機能はパッケージとバージョンにより異なるため、ダウンロードに含まれる説明を確認してください。"]
            ]
         },
         nl: {
            title: "Uitgebreide werkwijzen en belangrijke details",
            intro: "Deze uitleg vult de 22 screenshotbeschrijvingen aan en beschrijft het huidige gedrag van de add-on.",
            items: [
               ["Instellingen onderscheiden", "VFRNav opent op Map en biedt Map, Navlog, Charts, Settings en Credits. De add-oninstellingen zijn niet de algemene MSFS-EFB-instellingen: ze regelen kaartbronnen, lagen en optionele paneelaanpassingen in de geïntegreerde EFB. Verkleinen/vergroten wijzigt alleen het zichtbare gebied; verborgen onderdelen kunnen onklikbaar blijven. Als de 2D-formaatknoppen onbereikbaar zijn, herstelt Ctrl+Shift+rechtermuisknop de standaardgrootte."],
               ["Standaardlagen begrijpen", "Met verse standaardinstellingen zijn Google-kaartbeelden en de Franse OACI-kaart actief, evenals vliegvelden en AZBA-zones. De vliegtuigpositielaag staat standaard uit; schakel Settings > Map > Cheat > Plane in om het vliegtuig te tonen. Klik in Layers op een kaart om de laag te tonen/verbergen en sleep kaarten om de tekenvolgorde te wijzigen. Settings kan bronnen, vliegveldtypen en zoomgrenzen aanpassen; buiten het ingestelde bereik verdwijnt een laag."],
               ["Vluchtplannen maken en beheren", "Open op Map het vluchtplanpaneel (Nav), kies Create en teken de route door punten op de kaart te plaatsen en de tekening af te ronden. De route verschijnt in Nav en krijgt een Navlog-tab; meerdere routes kunnen naast elkaar bestaan. De routeknoppen activeren/verbergen, ordenen, hernoemen of verwijderen; sleep lijnpunten om de route aan te passen. De routezichtbaarheid staat los van kaartlagen."],
               ["Navlog lezen en zorgvuldig aanpassen", "Elke route heeft een eigen Navlog-tab; Settings bevat Compass- en Fuel-modellen. Kies Edit om beschikbare beenvelden te wijzigen en Done om af te sluiten. Beginwaarden zijn onder andere 95 kt snelheid, 300 brandstofeenheden en 15 minuten/30 eenheden voor taxitijd/-verbruik; dit zijn standaardwaarden, geen gecontroleerde vliegtuiggegevens. Vul passende gegevens in en gebruik berekende tijd, brandstof en koers alleen als planningshulp."],
               ["Alleen beschikbare kaartbronnen gebruiken", "Kies in Charts Open en daarna Local of SIA. Local opent een PDF op de hostcomputer en vereist de VFRNav-server of host-bestandsbrug; je kunt een paginanaam instellen. SIA accepteert Franse vliegveldcodes in het formaat LF**. TEMSI en Weather Fronts zijn zichtbaar als tabbladen, maar nog niet geïmplementeerd in de huidige code. Gebruik pijlen en +/- in de PDF-lezer; wiel scrollt verticaal, Ctrl+wiel horizontaal, Alt/Shift+wiel zoomt en linkermuisknop slepen verschuift."],
               ["Vliegveld- en AZBA-informatie beoordelen", "Schakel de vliegveldlaag in en zoom naar het zichtbare bereik (standaard minimale zoom 8); selecteer een marker. Het venster toont METAR/TAF en kan, afhankelijk van gegevens, frequenties, banen, overgangen of brandstof tonen; Charts verschijnt alleen voor Franse vliegvelden met een LF-code. Filters staan in Settings > Map > Airports. AZBA-zones tonen geplande Franse activiteit; selecteer een zone voor tijden, boven-/ondergrenzen en opmerkingen. Dit is geen ATC-toestemming; controleer actuele officiële informatie."],
               ["Vluchten worden automatisch opgenomen", "De geïntegreerde EFB registreert de positie zodra de simulator het vliegtuig als vliegend meldt; er is geen startknop. Na de landing wordt alleen opgeslagen als de vlucht langer dan vijf seconden duurde en een geldige niet-nul landingssnelheid beschikbaar is. Er blijven maximaal 15 recente vluchten bewaard. In Map > Records kun je routes tonen/verbergen, hernoemen of verwijderen; Alt+Shift+slepen draait de beoordelingskaart en het versleepbare persoonspictogram verandert het gezichtspunt. Settings > Data > Cleanup wist na bevestiging alle vluchtgegevens."],
               ["Wanneer de server nodig is", "Navlog Import en Export in de zelfstandige app gebruiken JSON-bestanden; Upload stuurt plannen naar de verbonden simulator-EFB en is uitgeschakeld zonder verbinding en in de geïntegreerde app. Charts-PDF's naar de simulator exporteren vereist ook verbinding. Lokale bestanden en overdracht tussen apps vereisen de VFRNav-server of host-bestandsbrug. Server- en externe-EFB-functies kunnen per pakket en versie verschillen; volg de instructies bij je download."]
            ]
         },
         pl: {
            title: "Szczegółowe procedury i ważne niuanse",
            intro: "Poniższe informacje uzupełniają 22 opisy zrzutów i przedstawiają aktualne zachowanie dodatku.",
            items: [
               ["Rozróżniaj ustawienia", "VFRNav otwiera się na Map i udostępnia Map, Navlog, Charts, Settings oraz Credits. Ustawienia dodatku nie są ogólnymi ustawieniami EFB MSFS: konfigurują źródła map, warstwy i opcjonalne poprawki panelu w zintegrowanym EFB. Zmiana rozmiaru dotyczy tylko widocznego obszaru; zasłonięte elementy mogą być nieklikalne. Jeśli przyciski 2D są niedostępne, Ctrl+Shift+kliknięcie prawym przyciskiem przywraca domyślny rozmiar."],
               ["Domyślne warstwy mapy", "Przy świeżych ustawieniach aktywne są obrazy map Google, francuska mapa OACI, lotniska i strefy AZBA. Warstwa pozycji samolotu jest domyślnie wyłączona; włącz Settings > Map > Cheat > Plane, aby pokazać samolot. W panelu Layers kliknij kartę, aby włączyć/ukryć warstwę, i przeciągaj karty, by zmienić kolejność. Settings pozwala wyłączać źródła, filtrować typy lotnisk i ustawiać zakres zoomu; poza zakresem warstwa znika."],
               ["Tworzenie i obsługa planów lotu", "Na Map otwórz panel planu (Nav), wybierz Create i narysuj trasę, umieszczając punkty na mapie, a następnie zakończ rysowanie. Trasa pojawia się w Nav i otrzymuje kartę Navlog; może istnieć kilka tras. Przyciski trasy pozwalają ją pokazać/ukryć, uporządkować, nazwać lub usunąć; przeciągaj wierzchołki linii, by zmienić przebieg. Widoczność trasy jest niezależna od warstw mapy."],
               ["Czytanie i edycja Navlogu", "Każda trasa ma własną kartę Navlog; Settings zawiera modele Compass i Fuel. Wybierz Edit, aby zmienić obsługiwane pola odcinka, a Done, by zakończyć edycję. Wartości początkowe to m.in. prędkość 95 kt, paliwo 300 jednostek oraz 15 min/30 jednostek czasu/spalania kołowania; są to wartości domyślne, nie sprawdzone dane samolotu. Wprowadź właściwe parametry i traktuj obliczenia czasu, paliwa i kursu jako pomoc planistyczną."],
               ["Korzystaj z zaimplementowanych źródeł kart", "W Charts wybierz Open, a potem Local lub SIA. Local otwiera PDF z komputera hosta i wymaga serwera VFRNav lub mostu plików hosta; dokument można nazwać. SIA przyjmuje francuskie kody lotnisk w formacie LF**. Zakładki TEMSI i Weather Fronts są widoczne, ale obecnie nie są zaimplementowane. W czytniku PDF używaj strzałek i +/-; kółko przewija pionowo, Ctrl+kółko poziomo, Alt/Shift+kółko powiększa, a przeciąganie lewym przyciskiem przesuwa stronę."],
               ["Interpretacja danych lotniska i AZBA", "Włącz warstwę lotnisk i przybliż do jej zakresu widoczności (domyślny minimalny zoom 8), a następnie wybierz symbol. Okno pokazuje METAR/TAF i może zawierać częstotliwości, pasy, poziomy przejściowe lub paliwo zależnie od danych; karta Charts jest tylko dla francuskich lotnisk o kodzie LF. Filtry znajdują się w Settings > Map > Airports. Obszary AZBA przedstawiają zaplanowaną aktywność we Francji; wybierz obszar, aby sprawdzić godziny, górne/dolne limity i uwagi. To nie jest zgoda ATC — sprawdzaj aktualne oficjalne informacje."],
               ["Nagrywanie lotów jest automatyczne", "Zintegrowane EFB rejestruje pozycję, gdy symulator wskazuje, że samolot jest w powietrzu; nie ma przycisku startu. Po lądowaniu zapis następuje tylko, jeśli lot trwał ponad pięć sekund i dostępna jest prawidłowa, niezerowa prędkość przyziemienia. Zachowywanych jest maksymalnie 15 ostatnich lotów. W Map > Records pokazuj/ukrywaj ślady, zmieniaj ich nazwy lub usuwaj; Alt+Shift+przeciągnięcie obraca mapę przeglądu, a przeciągany znacznik osoby zmienia punkt widoku. Settings > Data > Cleanup po potwierdzeniu usuwa wszystkie zapisane rekordy."],
               ["Kiedy potrzebny jest serwer", "Import i Export w Navlogu samodzielnej aplikacji obsługują pliki JSON; Upload wysyła plany do połączonego EFB symulatora i jest niedostępny bez połączenia oraz w aplikacji zintegrowanej. Eksport PDF z Charts do symulatora też wymaga połączenia. Lokalne pliki i transfer między aplikacjami zależą od serwera VFRNav lub mostu plików hosta. Funkcje serwera/zewnętrznego EFB zależą od pakietu i wersji; sprawdź instrukcje pobranego wydania."]
            ]
         },
         pt: {
            title: "Fluxos detalhados e particularidades importantes",
            intro: "Estas notas complementam as 22 explicações das imagens e descrevem o comportamento atual do complemento.",
            items: [
               ["Distinguir as definições", "O VFRNav abre em Map e inclui Map, Navlog, Charts, Settings e Credits. As definições do complemento são diferentes das definições gerais do EFB do MSFS: configuram mapas, camadas e ajustes opcionais do painel no EFB integrado. O redimensionamento altera apenas a área visível e pode deixar elementos tapados sem possibilidade de clique. Se os controlos 2D ficarem inacessíveis, Ctrl+Shift+clique direito repõe o tamanho predefinido."],
               ["Camadas predefinidas", "Com as definições iniciais, as imagens Google e a carta OACI de França estão ativas, assim como aeródromos e zonas AZBA. A camada da posição do avião está desativada; ative Settings > Map > Cheat > Plane para a mostrar. Em Layers, clique num cartão para mostrar/ocultar e arraste-o para alterar a ordem. Settings permite desativar fontes, filtrar tipos de aeródromo e definir limites de zoom; fora desse intervalo a camada desaparece."],
               ["Criar e gerir planos de voo", "Em Map, abra o painel do plano (Nav), escolha Create e desenhe a rota colocando vértices no mapa; termine o desenho. A rota aparece em Nav e cria um separador Navlog; podem existir várias rotas. Os controlos permitem ativar/ocultar, reordenar, renomear ou remover uma rota; arraste os vértices para alterar o percurso. A visibilidade da rota é independente das camadas do mapa."],
               ["Ler e editar o Navlog", "Cada rota tem um separador Navlog; Settings contém modelos Compass e Fuel. Escolha Edit para alterar campos de etapa disponíveis e Done para terminar a edição. Os valores iniciais incluem velocidade de 95 kt, 300 unidades de combustível e 15 min/30 unidades para tempo/consumo de táxi; são valores predefinidos, não dados verificados da aeronave. Introduza valores adequados e use os cálculos de tempo, combustível e rumo apenas como apoio ao planeamento."],
               ["Usar as fontes de cartas implementadas", "Em Charts, escolha Open e depois Local ou SIA. Local abre um PDF do computador anfitrião e requer o servidor VFRNav ou a integração de ficheiros do anfitrião; pode dar um nome à página. SIA aceita códigos de aeródromos franceses no formato LF**. TEMSI e Weather Fronts aparecem como separadores, mas ainda não estão implementados no código atual. No leitor PDF use setas e +/-; a roda percorre verticalmente, Ctrl+roda horizontalmente, Alt/Shift+roda amplia e arrastar com o botão esquerdo move a página."],
               ["Interpretar dados de aeródromos e AZBA", "Ative a camada de aeródromos e amplie até ao seu intervalo visível (zoom mínimo 8 por predefinição); selecione um símbolo. A janela mostra METAR/TAF e pode incluir frequências, pistas, transições ou combustível conforme os dados; o separador Charts só aparece em aeródromos franceses com código LF. Os filtros estão em Settings > Map > Airports. As zonas AZBA representam atividade francesa programada: selecione uma para consultar horários, limites superior/inferior e notas. Não é uma autorização ATC; confirme a informação oficial atual."],
               ["A gravação de voos é automática", "O EFB integrado regista a posição quando o simulador indica que o avião está no ar; não há botão de início. Após a aterragem, só guarda se o voo durou mais de cinco segundos e foi indicada uma velocidade de toque válida diferente de zero. São mantidos no máximo os 15 voos mais recentes. Em Map > Records, mostre/oculte trajetos, renomeie ou elimine; Alt+Shift+arrastar roda o mapa de revisão e o marcador de pessoa arrastável muda o ponto de vista. Settings > Data > Cleanup apaga todos os registos após confirmação."],
               ["Quando é necessário o servidor", "Import e Export do Navlog na aplicação autónoma usam ficheiros JSON; Upload envia planos ao EFB do simulador ligado e não está disponível sem ligação ou na aplicação integrada. Exportar PDFs de Charts para o simulador também requer ligação. O acesso a ficheiros locais e a transferência entre aplicações dependem do servidor VFRNav ou da integração de ficheiros do anfitrião. As funções de servidor/EFB externo variam por pacote e versão; consulte as instruções incluídas na transferência."]
            ]
         },
         "pt-BR": {
            title: "Fluxos detalhados e particularidades importantes",
            intro: "Estas notas complementam as 22 explicações das imagens e descrevem o comportamento atual do complemento.",
            items: [
               ["Diferencie as configurações", "O VFRNav abre em Map e oferece Map, Navlog, Charts, Settings e Credits. As configurações do complemento não são as configurações gerais do EFB do MSFS: elas ajustam mapas, camadas e opções do painel no EFB integrado. O redimensionamento altera somente a área visível e pode deixar itens cobertos sem clique. Se os controles 2D ficarem inacessíveis, Ctrl+Shift+clique direito restaura o tamanho padrão."],
               ["Camadas padrão", "Nas configurações iniciais, as imagens do Google e a carta OACI da França estão ativas, assim como aeroportos e áreas AZBA. A camada da posição do avião começa desativada; ative Settings > Map > Cheat > Plane para exibi-la. Em Layers, clique em um cartão para mostrar/ocultar e arraste para mudar a ordem. Settings permite desativar fontes, filtrar tipos de aeródromo e definir limites de zoom; fora do intervalo a camada desaparece."],
               ["Criar e gerenciar planos de voo", "Em Map, abra o painel de plano (Nav), escolha Create e desenhe a rota posicionando pontos no mapa; finalize o desenho. A rota aparece em Nav e cria uma aba Navlog; várias rotas podem coexistir. Os controles permitem ativar/ocultar, reordenar, renomear ou excluir a rota; arraste os vértices para alterar o traçado. A visibilidade da rota é independente das camadas do mapa."],
               ["Ler e editar o Navlog", "Cada rota tem uma aba Navlog; Settings contém modelos Compass e Fuel. Escolha Edit para alterar campos de trecho disponíveis e Done para encerrar a edição. Os valores iniciais incluem velocidade de 95 kt, 300 unidades de combustível e 15 min/30 unidades para tempo/consumo de táxi; são valores padrão, não dados confirmados da aeronave. Informe valores adequados e trate os cálculos de tempo, combustível e proa como auxílio ao planejamento."],
               ["Use apenas as fontes de cartas implementadas", "Em Charts, escolha Open e depois Local ou SIA. Local abre um PDF do computador anfitrião e requer o servidor VFRNav ou a ponte de arquivos do host; é possível definir um nome para a página. SIA aceita códigos de aeródromos franceses no formato LF**. TEMSI e Weather Fronts aparecem como abas, mas ainda não estão implementados no código atual. No leitor PDF use as setas e +/-; a roda rola verticalmente, Ctrl+roda horizontalmente, Alt/Shift+roda amplia e arrastar com o botão esquerdo move a página."],
               ["Interprete dados de aeródromo e AZBA", "Ative a camada de aeroportos e aproxime até o intervalo visível (zoom mínimo padrão 8); selecione um símbolo. A janela mostra METAR/TAF e pode incluir frequências, pistas, transições ou combustível conforme os dados; a aba Charts só aparece para aeródromos franceses com código LF. Os filtros ficam em Settings > Map > Airports. As áreas AZBA indicam atividade francesa programada: selecione uma para conferir horários, limites superior/inferior e observações. Isso não é autorização ATC; confirme as informações oficiais atuais."],
               ["A gravação de voos é automática", "O EFB integrado registra a posição quando o simulador indica que o avião está no ar; não existe botão de início. Após o pouso, só salva se o voo durou mais de cinco segundos e houve velocidade de toque válida diferente de zero. São mantidos no máximo os 15 voos mais recentes. Em Map > Records, mostre/oculte trajetos, renomeie ou exclua; Alt+Shift+arrastar gira o mapa de revisão e o marcador de pessoa arrastável muda o ponto de vista. Settings > Data > Cleanup apaga todos os registros após confirmação."],
               ["Quando o servidor é necessário", "Import e Export do Navlog no aplicativo independente usam arquivos JSON; Upload envia planos ao EFB do simulador conectado e não fica disponível sem conexão ou no aplicativo integrado. Exportar PDFs de Charts para o simulador também exige conexão. O acesso a arquivos locais e a transferência entre aplicativos dependem do servidor VFRNav ou da ponte de arquivos do host. Os recursos de servidor/EFB externo variam por pacote e versão; consulte as instruções do download."]
            ]
         },
         ru: {
            title: "Подробные сценарии и важные нюансы",
            intro: "Эти сведения дополняют 22 пояснения к снимкам и описывают текущее поведение дополнения.",
            items: [
               ["Различайте настройки", "VFRNav открывается на Map и содержит Map, Navlog, Charts, Settings и Credits. Настройки дополнения отличаются от общих настроек EFB в MSFS: они управляют картами, слоями и дополнительной настройкой панели во встроенной EFB. Изменение размера меняет только видимую область; перекрытые элементы могут быть недоступны. Если элементы изменения размера в 2D недоступны, Ctrl+Shift+правая кнопка возвращает стандартный размер."],
               ["Слои карты по умолчанию", "При исходных настройках активны подложка Google, французская карта OACI, аэропорты и зоны AZBA. Слой положения самолёта изначально выключен; включите Settings > Map > Cheat > Plane. В панели Layers щёлкните карточку, чтобы показать/скрыть слой, и перетащите её, чтобы изменить порядок. В Settings можно отключать источники, фильтровать типы аэропортов и задавать границы масштаба; за их пределами слой скрывается."],
               ["Создание и управление планами", "На Map откройте панель плана (Nav), выберите Create и нарисуйте маршрут точками на карте, завершив построение. Маршрут появится в Nav и получит вкладку Navlog; можно хранить несколько маршрутов. Управляйте показом, порядком, названием и удалением маршрутов; перетаскивайте вершины линии для изменения пути. Отображение маршрута не зависит от картографических слоёв."],
               ["Проверка и редактирование Navlog", "Для каждого маршрута есть вкладка Navlog; в Settings находятся модели Compass и Fuel. Нажмите Edit, чтобы изменить поддерживаемые поля участков, и Done для выхода. Начальные значения включают скорость 95 узлов, 300 единиц топлива и 15 минут/30 единиц на руление; это исходные значения, а не проверенные данные самолёта. Введите подходящие параметры и используйте расчёты времени, топлива и курса только как помощь при планировании."],
               ["Используйте реализованные источники карт", "В Charts нажмите Open, затем Local или SIA. Local открывает PDF с компьютера и требует VFRNav Server или файловый мост хоста; документу можно задать имя вкладки. SIA принимает коды французских аэродромов формата LF**. TEMSI и Weather Fronts отображаются как вкладки, но пока не реализованы в текущем коде. В PDF используйте стрелки и +/-; колесо прокручивает вертикально, Ctrl+колесо — горизонтально, Alt/Shift+колесо меняет масштаб, перетаскивание левой кнопкой перемещает страницу."],
               ["Сведения об аэродромах и AZBA", "Включите слой аэропортов и увеличьте масштаб до диапазона видимости (стандартный минимум — 8), затем выберите значок. Окно показывает METAR/TAF и, если данные доступны, частоты, полосы, эшелоны перехода или топливо; вкладка Charts доступна только для французских аэропортов с кодом LF. Фильтры находятся в Settings > Map > Airports. Зоны AZBA показывают запланированную активность во Франции; выберите зону, чтобы увидеть время, верхний/нижний пределы и примечания. Это не разрешение УВД — проверяйте официальные актуальные сведения."],
               ["Запись полёта выполняется автоматически", "Встроенная EFB записывает положение, когда симулятор считает самолёт находящимся в воздухе; кнопки запуска нет. После посадки запись сохраняется только при длительности более пяти секунд и ненулевой корректной скорости касания. Хранятся максимум 15 последних полётов. В Map > Records включайте показ треков, переименовывайте или удаляйте их; Alt+Shift+перетаскивание вращает карту обзора, а перемещение значка человека меняет точку зрения. Settings > Data > Cleanup после подтверждения удаляет все записи."],
               ["Когда требуется сервер", "Import/Export Navlog в автономном приложении работают с JSON-файлами; Upload отправляет планы в подключённую EFB симулятора и недоступен без соединения или во встроенном приложении. Экспорт PDF из Charts в симулятор также требует подключения. Локальные файлы и межпрограммная передача зависят от VFRNav Server или файлового моста хоста. Серверные функции и внешняя EFB могут отличаться по пакету и версии; следуйте инструкции к скачанной сборке."]
            ]
         },
         sv: {
            title: "Detaljerade arbetsflöden och viktiga nyanser",
            intro: "Dessa anteckningar kompletterar de 22 skärmbildsförklaringarna och beskriver tilläggets aktuella beteende.",
            items: [
               ["Skilj på inställningarna", "VFRNav öppnas på Map och har Map, Navlog, Charts, Settings och Credits. Tilläggets Settings är inte MSFS allmänna EFB-inställningar: de styr kartkällor, lager och valfria paneljusteringar i den integrerade EFB:n. Storleksändringen påverkar bara den synliga ytan; täckta objekt kan inte gå att klicka på. Om 2D-kontrollerna blir oåtkomliga återställer Ctrl+Shift+högerklick standardstorleken."],
               ["Förstå standardlager", "Med nya standardinställningar är Google-kartbilder, Frankrikes OACI-karta, flygplatser och AZBA-områden aktiva. Flygplanspositionslagret är avstängt; aktivera Settings > Map > Cheat > Plane för att visa planet. I Layers klickar du på ett kort för att visa/dölja lagret och drar korten för att ändra ritordning. Settings kan inaktivera källor, filtrera flygplatstyper och ange zoomgränser; lagret döljs utanför intervallet."],
               ["Skapa och hantera färdplaner", "Öppna färdplanspanelen (Nav) på Map, välj Create och rita rutten genom att placera punkter på kartan och avsluta ritningen. Rutten visas i Nav och får en Navlog-flik; flera rutter kan finnas samtidigt. Kontrollerna visar/döljer, sorterar, byter namn på eller tar bort rutter; dra linjens hörn för att ändra rutten. Ruttsynlighet är fristående från kartlager."],
               ["Läs och redigera Navlog", "Varje rutt har en Navlog-flik; Settings innehåller Compass- och Fuel-modeller. Välj Edit för att ändra tillgängliga sträckfält och Done för att avsluta. Startvärden omfattar 95 kt hastighet, 300 bränsleenheter och 15 min/30 enheter taxitid/-förbrukning; detta är standardvärden, inte verifierade flygplansdata. Ange lämpliga värden och använd beräknad tid, bränsle och kurs som planeringshjälp, inte garanti."],
               ["Använd implementerade kartkällor", "I Charts väljer du Open och sedan Local eller SIA. Local öppnar en PDF från värddatorn och kräver VFRNav-servern eller värdens filbrygga; dokumentet kan få ett sidnamn. SIA accepterar franska flygplatskoder i formatet LF**. TEMSI och Weather Fronts finns som flikar men är ännu inte implementerade i aktuell kod. I PDF-läsaren används pilar och +/-; hjulet rullar vertikalt, Ctrl+hjulet horisontellt, Alt/Skift+hjulet zoomar och vänsterdragning panorerar."],
               ["Tolka flygplats- och AZBA-data", "Aktivera flygplatslagret och zooma in i dess synlighetsområde (standardminsta zoom 8), välj sedan en markör. Fönstret visar METAR/TAF och kan visa frekvenser, banor, övergångar eller bränsle beroende på data; Charts-fliken visas endast för franska LF-flygplatser. Filtren finns under Settings > Map > Airports. AZBA-områden visar planerad fransk aktivitet; välj ett område för tider, övre/nedre gränser och kommentarer. Det är inget ATC-tillstånd – kontrollera aktuell officiell information."],
               ["Flyg spelas in automatiskt", "Den integrerade EFB:n registrerar positionen när simulatorn anger att flygplanet är i luften; det finns ingen startknapp. Efter landning sparas flygningen bara om den varade längre än fem sekunder och en giltig touchdownhastighet skild från noll rapporterades. Högst de 15 senaste flygningarna sparas. Under Map > Records kan du visa/dölja spår, byta namn eller ta bort dem; Alt+Skift+dra roterar granskningskartan och personmarkören kan dras för att ändra vy. Settings > Data > Cleanup raderar alla poster efter bekräftelse."],
               ["När servern behövs", "Navlog Import/Export i den fristående appen hanterar JSON-filer; Upload skickar planer till simulatorns anslutna EFB och är avstängt utan anslutning och i den integrerade appen. Export av PDF:er från Charts till simulatorn kräver också anslutning. Lokala filer och överföringar mellan appar beror på VFRNav-servern eller värdens filbrygga. Server- och extern-EFB-funktioner kan skilja sig mellan paket och versioner; följ instruktionerna för din nedladdning."]
            ]
         },
         tr: {
            title: "Ayrıntılı iş akışları ve önemli incelikler",
            intro: "Bu notlar yukarıdaki 22 ekran görüntüsü açıklamasını tamamlar ve eklentinin mevcut davranışını anlatır.",
            items: [
               ["Ayarları birbirinden ayırın", "VFRNav Map sayfasında açılır; Map, Navlog, Charts, Settings ve Credits sayfaları vardır. Eklentinin Settings sayfası MSFS'in genel EFB ayarları değildir; harita kaynaklarını, katmanları ve tümleşik EFB panelindeki isteğe bağlı düzenlemeleri yönetir. Boyutlandırma yalnızca görünür alanı değiştirir; arkasında kalan öğeler tıklanamaz olabilir. 2D boyut düğmelerine erişilemiyorsa Ctrl+Shift+sağ tıklama varsayılan boyutu geri getirir."],
               ["Varsayılan harita katmanları", "Yeni varsayılanlarda Google harita görüntüleri, Fransa OACI haritası, meydanlar ve AZBA alanları açıktır. Uçak konum katmanı başlangıçta kapalıdır; uçağı görmek için Settings > Map > Cheat > Plane öğesini açın. Layers panelinde karta tıklamak katmanı gösterir/gizler; kartları sürüklemek çizim sırasını değiştirir. Settings kaynakları kapatabilir, meydan türlerini filtreleyebilir ve yakınlaştırma sınırlarını ayarlayabilir; sınır dışına çıkınca katman gizlenir."],
               ["Uçuş planı oluşturma ve yönetme", "Map'te uçuş planı (Nav) panelini açıp Create'i seçin; haritada noktaları yerleştirerek rotayı çizin ve çizimi bitirin. Rota Nav paneline eklenir ve bir Navlog sekmesi oluşturur; birden fazla rota bulunabilir. Rota düğmeleri etkinleştirme/gizleme, sıralama, yeniden adlandırma ve silme işlemlerini yapar; çizgiyi düzenlemek için köşeleri sürükleyin. Rota görünürlüğü harita katmanlarından bağımsızdır."],
               ["Navlog'u okuyup düzenleme", "Her rotanın kendi Navlog sekmesi vardır; Settings bölümünde Compass ve Fuel modelleri bulunur. Edit ile desteklenen etap alanlarını değiştirin, Done ile düzenlemeyi bitirin. İlk değerler 95 kt hız, 300 yakıt birimi ve taksi süresi/tüketimi için 15 dk/30 birimdir; bunlar doğrulanmış uçak verileri değil varsayılanlardır. Uygun değerleri girin; hesaplanan süre, yakıt ve yönü garanti değil planlama yardımı olarak değerlendirin."],
               ["Yalnızca uygulanmış harita kaynakları", "Charts'ta Open, ardından Local veya SIA'yı seçin. Local bilgisayardaki PDF'yi açar ve VFRNav sunucusu/ana makine dosya köprüsü gerekir; belgeye sayfa adı verebilirsiniz. SIA yalnızca LF** biçimindeki Fransız meydan kodlarını kabul eder. TEMSI ve Weather Fronts sekmeleri görünür, ancak mevcut kodda henüz uygulanmamıştır. PDF'de oklar ve +/- kullanılır; tekerlek dikey kaydırır, Ctrl+tekerlek yatay, Alt/Shift+tekerlek yakınlaştırır, sol tuşla sürükleme sayfayı taşır."],
               ["Meydan ve AZBA verilerini yorumlama", "Meydan katmanını açıp görünürlük aralığına yakınlaştırın (varsayılan minimum zoom 8) ve bir simgeyi seçin. Pencere METAR/TAF gösterir; veri varsa frekanslar, pistler, geçişler veya yakıtı da sunabilir. Charts sekmesi yalnızca LF ile başlayan Fransız meydanlarında bulunur. Filtreler Settings > Map > Airports içindedir. AZBA alanları planlı Fransa etkinliğini gösterir; saatleri, üst/alt sınırları ve notları görmek için alanı seçin. Bu ATC izni değildir; güncel resmi bilgiyi doğrulayın."],
               ["Uçuş kaydı otomatiktir", "Tümleşik EFB, simülatör uçağın havada olduğunu bildirdiğinde konumu kaydeder; başlat düğmesi yoktur. İnişten sonra yalnızca uçuş beş saniyeden uzunsa ve sıfır olmayan geçerli touchdown hızı geldiyse kaydedilir. En fazla son 15 uçuş tutulur. Map > Records bölümünde izleri gösterip gizleyebilir, yeniden adlandırabilir veya silebilirsiniz; Alt+Shift+sürükleme inceleme haritasını döndürür, kişi işaretçisini sürüklemek bakış açısını değiştirir. Settings > Data > Cleanup onaydan sonra tüm kayıtları siler."],
               ["Sunucunun gerektiği durumlar", "Bağımsız uygulamadaki Navlog Import/Export JSON dosyaları kullanır; Upload planları bağlı simülatör EFB'sine yollar ve bağlantı yoksa veya tümleşik uygulamadaysa kullanılamaz. Charts PDF'lerini simülatöre aktarmak da bağlantı gerektirir. Yerel dosya erişimi ve uygulamalar arası aktarım VFRNav sunucusuna veya ana makinenin dosya köprüsüne bağlıdır. Sunucu/harici EFB özellikleri paket ve sürüme göre değişebilir; indirdiğiniz yapının talimatlarını izleyin."]
            ]
         },
         "zh-CN": {
            title: "详细操作流程与重要注意事项",
            intro: "以下内容补充前面的22项截图说明，介绍插件当前实际功能和容易混淆的细节。",
            items: [
               ["区分设置页面", "VFRNav 默认打开 Map，页面包括 Map、Navlog、Charts、Settings 和 Credits。插件的 Settings 不等于 MSFS 的通用 EFB 设置：它用于配置地图来源、图层，以及集成 EFB 中可选的面板调整。调整尺寸只改变可见区域，面板后方的控件可能无法点击。若无法操作 2D 尺寸控件，按 Ctrl+Shift+右键可恢复默认尺寸。"],
               ["了解默认地图图层", "新安装的默认设置会启用 Google 地图影像、法国 OACI 航图、机场和 AZBA 区域。飞机位置图层默认关闭；要显示飞机，请启用 Settings > Map > Cheat > Plane。在 Layers 面板中点击图层卡片可显示/隐藏，拖动卡片可调整绘制顺序。Settings 可以禁用地图来源、筛选机场类型并设置缩放范围；超出范围后图层会隐藏。"],
               ["创建和管理飞行计划", "在 Map 中打开飞行计划（Nav）面板，选择 Create，在地图上放置路线节点并完成绘制。新路线会出现在 Nav 面板，并生成对应的 Navlog 标签；可以同时保留多条路线。路线控制项可用于启用/隐藏、排序、重命名或删除；拖动路线顶点可调整路径。路线显示与地图图层显示相互独立。"],
               ["阅读和编辑 Navlog", "每条路线都有自己的 Navlog 标签；Settings 标签包含 Compass 和 Fuel 模型。选择 Edit 修改支持的航段字段，再选 Done 结束编辑。初始值包括速度 95 节、载油量 300 单位、滑行时间/消耗 15 分钟/30 单位；这些只是默认值，并非经过验证的飞机数据。请填写适合飞机和天气的值，并将计算出的时间、燃油和航向视为规划参考，而非保证值。"],
               ["仅使用已实现的航图来源", "在 Charts 中选择 Open，再选 Local 或 SIA。Local 用于打开主机上的 PDF，需要 VFRNav 服务器或主机文件桥接；可以为文档设置标签名称。SIA 只接受 LF** 格式的法国机场代码。TEMSI 和 Weather Fronts 虽显示为来源标签，但当前代码尚未实现。在 PDF 阅读器中使用翻页箭头和 +/-；滚轮垂直滚动，Ctrl+滚轮水平滚动，Alt/Shift+滚轮缩放，按住左键拖动可平移页面。"],
               ["正确理解机场与 AZBA 信息", "启用机场图层并放大到其可见范围（默认最小缩放级别为8），然后选择机场标记。弹窗显示 METAR/TAF，并根据数据提供频率、跑道、过渡高度或燃油信息；Charts 标签仅对 LF 开头的法国机场显示。筛选项在 Settings > Map > Airports。AZBA 区域表示法国计划中的活动；选择区域可查看时间段、高/低高度限制和备注。这不是 ATC 放行许可；飞行前请核对最新官方信息。"],
               ["飞行记录自动生成", "集成 EFB 会在模拟器报告飞机离地时自动记录位置，没有手动开始按钮。着陆后，仅当飞行超过五秒且获得有效的非零接地速度时才保存记录。最多保留最近15次飞行。在 Map > Records 中可显示/隐藏航迹、重命名或删除；Alt+Shift+拖动可旋转回顾地图，拖动人物标记可改变视角。Settings > Data > Cleanup 经确认后会永久清除全部飞行记录。"],
               ["了解何时需要服务器", "独立应用中 Navlog 的 Import/Export 使用 JSON 文件；Upload 会将计划发送到已连接的模拟器 EFB，未连接或在集成应用内时不可用。从 Charts 向模拟器导出 PDF 也需要连接。访问本地文件和跨应用传输依赖 VFRNav 服务器或主机文件桥接。服务器/外部浏览器 EFB 功能可能因安装包和版本而异，请遵循下载版本附带的说明。"]
            ]
         }
      } satisfies LocaleMap<DetailedGuide>;

